System.Collections.IEnumerator Run(){
 var rig=UnityEngine.Object.FindObjectOfType<Character.Control.PaddleCharacterVisual>();
 rig.body.GetComponent<UnityEngine.Rigidbody2D>().constraints=UnityEngine.RigidbodyConstraints2D.FreezeAll;
 foreach(var c in UnityEngine.Object.FindObjectsOfType<Cinemachine.CinemachineVirtualCamera>())c.enabled=false;
 var cam=UnityEngine.Camera.main;cam.orthographicSize=2.7f;cam.transform.position=rig.body.position+new UnityEngine.Vector3(0,.3f,-10);
 var first=rig.tip.position;float maxMove=0,maxError=0,minGap=100,maxAngleStep=0;float lastAngle=rig.leftUpper.transform.eulerAngles.z;
 for(int i=0;i<120;i++){
  float angle=i*UnityEngine.Mathf.PI*4/120;
  float radius=1.15f+UnityEngine.Mathf.Sin(i*.13f)*.8f;
  var world=rig.body.position+new UnityEngine.Vector3(UnityEngine.Mathf.Cos(angle),UnityEngine.Mathf.Sin(angle),0)*radius;
  var screen=cam.WorldToScreenPoint(world);
  UnityEngine.InputSystem.InputSystem.QueueStateEvent(UnityEngine.InputSystem.Mouse.current,new UnityEngine.InputSystem.LowLevel.MouseState{position=new UnityEngine.Vector2(screen.x,screen.y)});
  yield return new UnityEngine.WaitForFixedUpdate();yield return null;
  maxMove=UnityEngine.Mathf.Max(maxMove,UnityEngine.Vector3.Distance(first,rig.tip.position));
  maxError=UnityEngine.Mathf.Max(maxError,rig.HandError);minGap=UnityEngine.Mathf.Min(minGap,UnityEngine.Vector3.Distance(rig.LeftHand,rig.RightHand));
  maxAngleStep=UnityEngine.Mathf.Max(maxAngleStep,UnityEngine.Mathf.Abs(UnityEngine.Mathf.DeltaAngle(lastAngle,rig.leftUpper.transform.eulerAngles.z)));lastAngle=rig.leftUpper.transform.eulerAngles.z;
  if(i%30==15){UnityEngine.ScreenCapture.CaptureScreenshot(System.IO.Path.GetFullPath("scripts/player-frame-arms-20261111/input-"+i+".png"));}
 }
 string log="Actual mouse input / dynamic paddle: max tip travel="+maxMove+" max wrist error="+maxError+" min hand spacing="+minGap+" max sampled elbow angle step="+maxAngleStep;
 System.IO.File.WriteAllText("scripts/player-frame-arms-20261111/input.txt",log);UnityEngine.Debug.Log(log);
 if(minGap<.12f)throw new System.Exception("Fixed targets collapsed");
}
return Run();
